<template><section class="g-advanced-filter"><div v-for="(c,i) in modelValue" :key="i" class="condition"><el-select v-model="c.field" placeholder="字段"><el-option v-for="f in fields" :key="f.value" :label="f.label" :value="f.value"/></el-select><el-select v-model="c.operator"><el-option label="等于" value="eq"/><el-option label="包含" value="contains"/><el-option label="不等于" value="neq"/></el-select><el-input v-model="c.value"/><el-button link type="danger" @click="remove(i)">删除</el-button></div><el-button @click="add">＋ 添加条件</el-button><el-button type="primary" @click="$emit('apply',modelValue)">应用筛选</el-button></section></template><script setup>
const p=defineProps({modelValue:{type:Array,required:true},fields:{type:Array,required:true}});const emit=defineEmits(["update:modelValue","apply"]);const add=()=>emit('update:modelValue',[...p.modelValue,{field:'',operator:'eq',value:''}]);const remove=(i)=>emit('update:modelValue',p.modelValue.filter((_,n)=>n!==i));
</script><style lang="less" scoped>
.g-advanced-filter{display:grid;gap:var(--space-12);padding:var(--space-16);background:var(--g-bg-surface)}.condition{display:grid;grid-template-columns:var(--spec-gadvanced-filter-grid-template-columns);gap:var(--space-8)}
</style>
